const now = Date.now();
const rows = $input.all().map(item => item.json || {}).filter(row => String(row.questionId || '').trim());
function time(value, fallback = 0) { const parsed = Date.parse(String(value || '')); return Number.isFinite(parsed) ? parsed : fallback; }
function lane(row) {
  return `${String(row.memoryTenantId || row.tenantId || '').trim()}\u0000${String(row.chatId || '').trim()}`;
}
const logicalCounts = new Map();
for (const row of rows) {
  const tenant = String(row.memoryTenantId || row.tenantId || '').trim();
  for (const identity of [String(row.questionId || '').trim(), String(row.questionRowKey || '').trim()].filter(Boolean)) {
    const key = `${tenant}\u0000${identity}`;
    logicalCounts.set(key, Number(logicalCounts.get(key) || 0) + 1);
  }
}
for (const [key, count] of logicalCounts) {
  if (count !== 1) throw new Error(`Resolution dispatcher found ${count} physical rows for logical key ${key}.`);
}
const liveStatuses = new Set(['answer_queued', 'applying']);
const blockedLanes = new Set(rows.filter(row => {
  const status = String(row.status || '').trim().toLowerCase();
  if (liveStatuses.has(status)) return true;
  if (status === 'asked') {
    const askedAt = time(row.askedAt, 0);
    const fallbackExpiry = askedAt ? askedAt + 72 * 60 * 60 * 1000 : 0;
    return time(row.askedExpiresAt, fallbackExpiry) > now;
  }
  if (status === 'dispatching') return time(row.dispatchLeaseUntil, 0) > now;
  if (status === 'answer_claimed') return time(row.answerClaimLeaseUntil, 0) > now;
  return false;
}).map(lane));

const eligible = rows.map(row => {
  const status = String(row.status || '').trim().toLowerCase();
  if (status === 'answer_claimed' && time(row.answerClaimLeaseUntil, 0) <= now
    && String(row.answerMessageId || '').trim() && String(row.answerText || '').trim()) {
    return { ...row, dispatcherAction: 'recover_answer', dispatcherActionPriority: 2 };
  }
  if (status === 'pending' || (status === 'dispatching' && time(row.dispatchLeaseUntil, 0) <= now)) {
    return { ...row, dispatcherAction: 'ask_question', dispatcherActionPriority: 1 };
  }
  return null;
}).filter(Boolean).filter(row => !blockedLanes.has(lane(row)))
  .sort((a, b) => Number(b.dispatcherActionPriority || 0) - Number(a.dispatcherActionPriority || 0)
    || Number(b.priority || 0) - Number(a.priority || 0)
    || time(a.sourceMessageDateIso, Number.MAX_SAFE_INTEGER) - time(b.sourceMessageDateIso, Number.MAX_SAFE_INTEGER)
    || String(a.questionId).localeCompare(String(b.questionId)));

return [{ json: eligible.length
  ? { ...eligible[0], hasPendingResolutionQuestion: true }
  : { hasPendingResolutionQuestion: false, dispatcherStatus: 'idle' }
}];

const row = $input.first()?.json || {};
function text(value) { return String(value ?? '').trim(); }
function time(value) { const parsed = Date.parse(text(value)); return Number.isFinite(parsed) ? parsed : 0; }

if (row.dispatcherAction !== 'recover_answer' || text(row.status) !== 'answer_claimed') {
  throw new Error('Dispatcher answer recovery requires an expired answer_claimed row.');
}
if (time(row.answerClaimLeaseUntil) > Date.now()) throw new Error('Dispatcher cannot recover a live answer claim.');
if (!text(row.questionId) || !text(row.answerMessageId) || !text(row.answerText)
  || !text(row.memoryTenantId || row.tenantId) || !text(row.chatId)) {
  throw new Error('Dispatcher answer recovery identity is incomplete.');
}

return [{ json: {
  operationMode: 'enqueue_answer',
  resolutionQuestionId: text(row.questionId),
  resolutionQuestionType: text(row.questionType),
  resolutionQuestionJson: JSON.stringify(row),
  resolutionTargetPointId: text(row.qdrantQuestionPointId),
  resolutionContextJson: text(row.contextJson) || '{}',
  answerText: text(row.answerText),
  selectedRef: text(row.selectedRef),
  answerMessageId: text(row.answerMessageId),
  messageId: text(row.answerMessageId),
  messageDateIso: text(row.answeredAt || row.sourceMessageDateIso),
  callbackQueryId: '',
  callbackData: '',
  telegramUserId: text(row.telegramUserId),
  chatId: text(row.chatId),
  userId: text(row.userId),
  memoryUserId: text(row.memoryUserId),
  tenantId: text(row.tenantId || row.memoryTenantId),
  memoryTenantId: text(row.memoryTenantId || row.tenantId),
  qdrantCollection: text(row.qdrantCollection),
  dispatcherRecoveryQuestionId: text(row.questionId),
  dispatcherRecoveryAnswerMessageId: text(row.answerMessageId),
  dispatcherRecoveryReady: true,
  dispatcherRecoveryVersion: 'chelsea_resolution_dispatcher_recovery_v2_1'
} }];

const expected = $('Code | Build Expired Answer Recovery | DispatchResolution').first().json || {};
const response = $input.first()?.json || {};
function text(value) { return String(value ?? '').trim(); }

const questionId = text(response.questionId || response.resolutionQuestionId);
const status = text(response.status || response.resolutionQuestionStatus).toLowerCase();
const answerMessageId = text(response.answerMessageId);
const jobId = text(response.jobId || response.resolutionQuestionJobId);
const acceptedStatuses = new Set(['answer_queued', 'applying', 'resolved', 'rejected', 'closed', 'pending']);
if (questionId !== text(expected.dispatcherRecoveryQuestionId)
  || answerMessageId !== text(expected.dispatcherRecoveryAnswerMessageId)
  || !acceptedStatuses.has(status) || !jobId) {
  throw new Error('Dispatcher could not verify recovered durable answer enqueue.');
}
return [{ json: {
  questionId,
  resolutionQuestionId: questionId,
  answerMessageId,
  jobId,
  status,
  dispatcherRecoveryVerified: true,
  dispatcherRecoveryVerifiedAt: new Date().toISOString()
} }];

const row = $input.first()?.json || {};
if (row.hasPendingResolutionQuestion !== true || !row.questionId || !row.questionToken) throw new Error('Dispatcher claim input is incomplete.');
const now = new Date();
return [{ json: {
  ...row,
  previousDispatchStatus: String(row.status || ''),
  previousDispatchLeaseOwner: String(row.dispatchLeaseOwner || ''),
  previousDispatchLeaseUntil: String(row.dispatchLeaseUntil || ''),
  previousDispatchAttemptCount: Number(row.dispatchAttemptCount || 0),
  status: 'dispatching',
  dispatchLeaseOwner: `dispatcher:${String($workflow.id)}:${String($execution.id)}`,
  dispatchLeaseUntil: new Date(now.getTime() + 5 * 60 * 1000).toISOString(),
  dispatchAttemptCount: Number(row.dispatchAttemptCount || 0) + 1,
  dispatchClaimedAt: now.toISOString(),
  stateChangedAt: now.toISOString()
} }];

const expected = $('Code | Build Resolution Dispatch Claim | DispatchResolution').first().json || {};
const matchedRows = $input.all().map(item => item.json || {}).filter(item => String(item.questionId || '').trim());
if (matchedRows.length !== 1) throw new Error(`Resolution dispatcher claim read-back cardinality is ${matchedRows.length}.`);
const row = matchedRows[0];
if (String(row.questionId || '') !== String(expected.questionId || '')) throw new Error('Dispatcher claim questionId mismatch.');
if (String(row.memoryTenantId || row.tenantId || '') !== String(expected.memoryTenantId || expected.tenantId || '')) throw new Error('Dispatcher claim tenant mismatch.');
if (String(row.rowInstanceId || '') !== String(expected.rowInstanceId || '')) throw new Error('Dispatcher claim rowInstanceId mismatch.');
if (String(row.status || '') !== 'dispatching') throw new Error('Dispatcher claim status was not persisted.');
if (String(row.dispatchLeaseOwner || '') !== String(expected.dispatchLeaseOwner || '')) throw new Error('Dispatcher lease owner was not confirmed; another execution owns the question.');
if (String(row.dispatchLeaseUntil || '') !== String(expected.dispatchLeaseUntil || '')) throw new Error('Dispatcher lease deadline mismatch.');
return [{ json: { ...row, hasPendingResolutionQuestion: true, dispatchClaimVerified: true } }];

const row = $input.first()?.json || {};
function text(value, fallback = '') { const result = String(value ?? '').trim(); return result || fallback; }
function parse(value, fallback) { try { return typeof value === 'object' ? value : JSON.parse(String(value || '')); } catch (error) { return fallback; } }

if (text(row.status).toLowerCase() !== 'dispatching' || row.dispatchClaimVerified !== true) {
  throw new Error('Dispatcher received a question without a verified dispatch lease.');
}
if (!text(row.questionId) || !text(row.chatId) || !text(row.questionText)) {
  throw new Error('Dispatcher question is missing questionId, chatId, or questionText.');
}
if (!['person_resolution', 'memory_conflict'].includes(text(row.questionType))) {
  throw new Error('Dispatcher received an unsupported questionType.');
}

const options = parse(row.callbackOptionsJson, []).filter(option => option && text(option.label) && text(option.callbackData)).slice(0, 8);
const rows = [];
for (let index = 0; index < options.length; index += 2) {
  rows.push({ row: { buttons: options.slice(index, index + 2).map(option => ({
    text: text(option.label).slice(0, 60),
    additionalFields: { callback_data: text(option.callbackData).slice(0, 64) }
  })) } });
}

const instruction = row.questionType === 'memory_conflict'
  ? 'Выберите вариант или ответьте на это сообщение своим текстом.'
  : 'Выберите человека или ответьте на это сообщение, уточнив имя.';
const valueContext = row.questionType === 'memory_conflict'
  ? `\n\nПрежнее значение: ${text(row.existingValue)}\nНовое значение: ${text(row.incomingValue)}`
  : '';

return [{ json: {
  ...row,
  dispatchReady: true,
  telegramText: `${text(row.questionText)}${valueContext}\n\n${instruction}\n\nКод вопроса: ${text(row.questionToken)}`.slice(0, 4000),
  inlineKeyboard: { rows },
  dispatchAttemptAt: new Date().toISOString(),
  dispatcherVersion: 'chelsea_resolution_dispatcher_v2_0'
} }];

const source = $('Code | Build Telegram Resolution Question | DispatchResolution').first().json || {};
const response = $input.first()?.json || {};
function text(value, fallback = '') { const result = String(value ?? '').trim(); return result || fallback; }

const telegramMessageId = text(response.message_id || response.result?.message_id || response.message?.message_id);
const responseChatId = text(response.chat?.id || response.result?.chat?.id, source.chatId);
if (!telegramMessageId || !responseChatId) {
  throw new Error('Telegram dispatcher did not return message_id and chat.id.');
}
const askedAt = new Date();

return [{ json: {
  ...source,
  status: 'asked',
  telegramQuestionMessageId: telegramMessageId,
  correlationKey: `tg:${responseChatId}:${telegramMessageId}`,
  askedAt: askedAt.toISOString(),
  askedExpiresAt: new Date(askedAt.getTime() + 72 * 60 * 60 * 1000).toISOString(),
  stateChangedAt: askedAt.toISOString(),
  dispatchResponseVerified: true
} }];

const expected = $('Code | Verify Telegram Resolution Receipt | DispatchResolution').first().json || {};
const rows = $input.all().map(item => item.json || {}).filter(row => String(row.questionId || '').trim());
if (rows.length !== 1) throw new Error(`Resolution asked read-back cardinality is ${rows.length}.`);
const row = rows[0];
function text(value) { return String(value ?? '').trim(); }
for (const field of [
  'questionId', 'memoryTenantId', 'rowInstanceId', 'status', 'telegramQuestionMessageId',
  'correlationKey', 'askedAt', 'askedExpiresAt', 'stateChangedAt'
]) {
  const actual = field === 'memoryTenantId' ? row.memoryTenantId || row.tenantId : row[field];
  const wanted = field === 'memoryTenantId' ? expected.memoryTenantId || expected.tenantId : expected[field];
  if (text(actual) !== text(wanted)) throw new Error(`Resolution asked ${field} mismatch.`);
}
if (text(row.dispatchLeaseOwner) || text(row.dispatchLeaseUntil)) throw new Error('Resolution asked dispatch lease was not released.');
return [{ json: { ...row, resolutionAskedVerified: true } }];

'use strict';
const rows=$input.all().map(item=>item.json||{});const out=[];
const text=v=>String(v??'').normalize('NFKC').trim();const username=v=>text(v).replace(/^@+/,'').toLowerCase();
for(const input of rows){
  if(input.hasPendingResolutionQuestion===false){out.push({json:{...input,noPendingIdentityRequired:true}});continue;}
  const storageUsername=username(input.storageUsername||input.userId||input.memoryUserId);
  const telegramActorId=text(input.telegramActorId||input.telegramUserId);
  if(!/^actor_[a-f0-9]{32}$/.test(storageUsername))throw new Error('stored actor identity: invalid storageUsername');
  if(!/^\d+$/.test(telegramActorId)||Number(telegramActorId)<=0)throw new Error('stored actor identity: numeric Telegram actor required');
  const currentUsername=username(input.currentUsername||input.telegramUsername||'');if(currentUsername&&!/^[a-z0-9_]{1,64}$/.test(currentUsername))throw new Error('stored actor identity: invalid currentUsername alias');
  const expected={userId:storageUsername,memoryUserId:storageUsername,tenantId:`tenant_${storageUsername}`,memoryTenantId:`tenant_${storageUsername}`,qdrantCollection:`kb_tenant_${storageUsername}`};
  for(const key of ['userId','memoryUserId','tenantId','memoryTenantId','qdrantCollection']){if(text(input[key])&&text(input[key])!==expected[key])throw new Error(`stored actor identity: ${key} mismatch`);}
  const principalKey=text(input.principalKey);if(!/^tgactor_[a-f0-9]{64}$/.test(principalKey))throw new Error('stored actor identity: invalid principalKey');
  out.push({json:{...input,...expected,principalKey,storageUsername,currentUsername,telegramUsername:currentUsername,telegramActorId,telegramUserId:telegramActorId,soulId:text(input.soulId)||`chelsea_soul_${storageUsername}`,identitySchemaVersion:'chelsea_actor_identity_v3',identityStatus:text(input.identityStatus)||'active',storedIdentityBoundaryVerified:true}});
}
return out;
